<template><el-dialog :model-value="modelValue" title="导出模型" width="520px" :close-on-click-modal="false" @update:model-value="$emit('update:modelValue',$event)"><el-form label-position="top"><el-form-item label="版本号"><el-input v-model="form.version" placeholder="自动生成，或输入 v1.0.0"/></el-form-item><el-form-item label="版本描述"><el-input v-model="form.description" type="textarea" :rows="3" placeholder="描述本次训练的主要变更"/></el-form-item><el-form-item v-if="isAdmin" label="设为场景默认模型"><el-switch v-model="form.set_default"/><span class="hint">仅管理员可操作，并按场景生效</span></el-form-item><el-form-item label="上传 MinIO"><el-switch v-model="form.upload_minio"/></el-form-item></el-form><el-alert v-if="!isAdmin" type="info" :closable="false" title="普通用户导出的模型不会自动切换为场景默认模型。"/><template #footer><el-button :disabled="loading" @click="$emit('update:modelValue',false)">取消</el-button><el-button type="primary" :loading="loading" @click="$emit('submit')">确认导出</el-button></template></el-dialog></template>
<script setup>defineProps({modelValue:Boolean,form:{type:Object,required:true},isAdmin:Boolean,loading:Boolean});defineEmits(['update:modelValue','submit'])</script>
<style lang="scss" scoped>.hint{margin-left:8px;color:$text-secondary;font-size:12px}</style>
